#include <stdio.h>

int main(void) {
    double c;

    return 0;
}

steps.solution:
#include <stdio.h>

int main(void) {
    double c;
    scanf("%lf", &c);
    double f = c * 9 / 5 + 32;
    printf("%.1f\n", f);
    return 0;
}

