int main(void) {
    int g[3][3];
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 3; c++)
            scanf("%d", &g[r][c]);
    for (int r = 0; r < 3; r++) {
        int s = 0;
        for (int c = 0; c < 3; c++) s += g[r][c];
