    char a[] = "a b  c";
    squeeze(a);
    CHECK_STR("\"a b  c\"", a, "abc");
    char b[] = "   rush b   ";
    squeeze(b);
    CHECK_STR("leading and trailing", b, "rushb");
    char c[] = "nospace";
    squeeze(c);
    CHECK_STR("no spaces", c, "nospace");
    char d[] = "    ";
    squeeze(d);
    CHECK_STR("only spaces", d, "");
    return 0;
}

