    int ok = 1;
    for (int i = 0; i < 5; i++) if (a[i] != i) ok = 0;
    CHECK("range(5) is {0,1,2,3,4}", ok);
    free(a);
    int *b = range(1000);
    CHECK_INT("range(1000)[999]", b[999], 999);
    free(b);
    return 0;
}

