#include <stdio.h>
#include <string.h>

static int add(int a, int b) { return a + b; }
static int sub(int a, int b) { return a - b; }
static int mul(int a, int b) { return a * b; }

typedef struct {
    const char *name;
    int (*fn)(int, int);
} Command;

static const Command commands[] = {
    {"add", add},
    {"sub", sub},
    {"mul", mul},
};
static const int NCOMMANDS = sizeof commands / sizeof commands[0];

int main(void) {
    char name[16];
    int a, b;
    while (scanf("%15s %d %d", name, &a, &b) == 3) {
        // find the command and print its result, or "unknown NAME"
        const Command *found = NULL;
        for (int i = 0; i < NCOMMANDS; i++) {
            if (strcmp(commands[i].name, name) == 0) found = &commands[i];
        }
        if (found) printf("%d\n", found->fn(a, b));
        else printf("unknown %s\n", name);
    }
    return 0;
}

