#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[16];
    int score;
} Player;

static int by_score_desc(const void *pa, const void *pb) {
    const Player *a = pa, *b = pb;
    if (a->score != b->score) return (b->score > a->score) - (b->score < a->score);
    return strcmp(a->name, b->name);
}

void sort_players(Player *p, size_t n) {
    qsort(p, n, sizeof *p, by_score_desc);
}

