#include <stddef.h>

typedef void (*Handler)(int event, void *ctx);

#define MAX_HANDLERS 8

typedef struct {
    Handler handlers[MAX_HANDLERS];
    void *contexts[MAX_HANDLERS];
    int count;
} Bus;

int bus_on(Bus *b, Handler h, void *ctx) {
    if (b->count >= MAX_HANDLERS) return -1;
    b->handlers[b->count] = h;
    b->contexts[b->count] = ctx;
    b->count++;
    return 0;
}

void bus_emit(Bus *b, int event) {
    for (int i = 0; i < b->count; i++) b->handlers[i](event, b->contexts[i]);
}

