static double absd(double x) { return x < 0 ? -x : x; }

int nearly_equal(double a, double b, double eps) {
    double scale = 1.0;
    if (absd(a) > scale) scale = absd(a);
    if (absd(b) > scale) scale = absd(b);
    return absd(a - b) <= eps * scale;
}

