    CHECK_INT("1.0 vs 1.1", nearly_equal(1.0, 1.1, 1e-9), 0);
    CHECK_INT("big numbers scale the tolerance", nearly_equal(1e12, 1e12 + 1, 1e-9), 1);
    CHECK_INT("small numbers use absolute tolerance", nearly_equal(1e-12, 0.0, 1e-9), 1);
