#include <numeric>
#include <string>

class Fraction {
public:
    Fraction(int num, int den = 1) : num_(num), den_(den) {
        if (den_ < 0) {
            num_ = -num_;
            den_ = -den_;
        }
        int g = std::gcd(num_, den_);
        if (g > 1) {
            num_ /= g;
            den_ /= g;
        }
    }
    int num() const { return num_; }
    int den() const { return den_; }
    Fraction plus(const Fraction& o) const { return Fraction(num_ * o.den_ + o.num_ * den_, den_ * o.den_); }
    Fraction times(const Fraction& o) const { return Fraction(num_ * o.num_, den_ * o.den_); }
    std::string str() const {
        if (den_ == 1) return std::to_string(num_);
        return std::to_string(num_) + "/" + std::to_string(den_);
    }

private:
    int num_;
    int den_;
};

steps.harness:
int main() {
    CHECK_EQ("6/8 reduces", Fraction(6, 8).str(), std::string("3/4"));
    CHECK_EQ("2/-4 moves the sign", Fraction(2, -4).str(), std::string("-1/2"));
    CHECK_EQ("-3/-9", Fraction(-3, -9).str(), std::string("1/3"));
    CHECK_EQ("4/2 prints as 2", Fraction(4, 2).str(), std::string("2"));
    CHECK_EQ("0/5 is 0", Fraction(0, 5).str(), std::string("0"));
    CHECK_EQ("whole number", Fraction(7).str(), std::string("7"));
    CHECK_EQ("1/2 + 1/3", Fraction(1, 2).plus(Fraction(1, 3)).str(), std::string("5/6"));
    CHECK_EQ("1/2 + 1/2", Fraction(1, 2).plus(Fraction(1, 2)).str(), std::string("1"));
    CHECK_EQ("2/3 * 3/4", Fraction(2, 3).times(Fraction(3, 4)).str(), std::string("1/2"));
    Fraction f(10, -20);
    CHECK("num and den after reducing", f.num() == -1 && f.den() == 2);
}

