#include <functional>
#include <utility>

class ScopeGuard {
public:
    explicit ScopeGuard(std::function<void()> f) : f_(std::move(f)) {}
    ~ScopeGuard() {
        if (active_ && f_) f_();
    }
    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;
    void dismiss() { active_ = false; }

private:
    std::function<void()> f_;
    bool active_ = true;
};

steps.harness:
#include <type_traits>
int early(int& log) {
    ScopeGuard g([&log] { log += 1; });
    if (log >= 0) return 5;
    return 6;
}
int main() {
    int runs = 0;
    {
        ScopeGuard g([&runs] { runs++; });
        CHECK_EQ("not run while in scope", runs, 0);
    }
    CHECK_EQ("runs at end of scope", runs, 1);
    {
        ScopeGuard g([&runs] { runs++; });
        g.dismiss();
    }
    CHECK_EQ("dismissed guard does not run", runs, 1);
    int log = 0;
    CHECK_EQ("early return still returns", early(log), 5);
    CHECK_EQ("runs on early return", log, 1);
    CHECK("not copyable", !std::is_copy_constructible_v<ScopeGuard>);
}

