A vector of vectors makes a grid whose size is decided at runtime:

```cpp
std::vector<std::vector<int>> grid(rows, std::vector<int>(cols, 0));
grid[r][c] = 5;
```

**Your turn:** write `std::vector<std::vector<int>> transpose(const std::vector<std::vector<int>>& m)` that swaps rows and columns. A 2x3 matrix becomes 3x2. You can assume every row has the same length and there's at least one row.

steps.seed:
#include <vector>

std::vector<std::vector<int>> transpose(const std::vector<std::vector<int>>& m) {

}

steps.solution:
#include <vector>

std::vector<std::vector<int>> transpose(const std::vector<std::vector<int>>& m) {
    std::size_t rows = m.size(), cols = m[0].size();
    std::vector<std::vector<int>> t(cols, std::vector<int>(rows));
    for (std::size_t r = 0; r < rows; r++)
        for (std::size_t c = 0; c < cols; c++)
            t[c][r] = m[r][c];
    return t;
}

steps.harness:
int main() {
    std::vector<std::vector<int>> m = {{1, 2, 3}, {4, 5, 6}};
    auto t = transpose(m);
    CHECK_EQ("rows", t.size(), 3);
    CHECK_EQ("row 0", t[0], std::vector<int>{1, 4});
    CHECK_EQ("row 2", t[2], std::vector<int>{3, 6});
    auto one = transpose({{7}});
    CHECK_EQ("1x1", one[0], std::vector<int>{7});
}

