    using V = std::vector<std::string>;
    CHECK_EQ("a,b,c", split("a,b,c", ','), V{"a", "b", "c"});
    CHECK_EQ("a,,b", split("a,,b", ','), V{"a", "", "b"});
    CHECK_EQ("empty", split("", ','), V{""});
    CHECK_EQ("no separator", split("dust2", ','), V{"dust2"});
    CHECK_EQ("spaces", split("rush b now", ' '), V{"rush", "b", "now"});
    CHECK_EQ("trailing sep", split("x;", ';'), V{"x", ""});
}

