steps.solution:
#include <unordered_map>
#include <utility>
#include <vector>

std::pair<int, int> two_sum(const std::vector<int>& v, int target) {
    std::unordered_map<int, int> seen;
    for (int j = 0; j < (int)v.size(); j++) {
        auto it = seen.find(target - v[j]);
        if (it != seen.end()) return {it->second, j};
        seen[v[j]] = j;
    }
    return {-1, -1};
}

steps.harness:
