    auto a = two_sum({2, 7, 11, 15}, 9);
    CHECK("2+7=9 -> {0,1}", a.first == 0 && a.second == 1);
    auto b = two_sum({3, 2, 4}, 6);
    CHECK("2+4=6 -> {1,2}", b.first == 1 && b.second == 2);
    auto c = two_sum({1, 2, 3}, 100);
    CHECK("none -> {-1,-1}", c.first == -1 && c.second == -1);
    auto d = two_sum({5, 5}, 10);
    CHECK("5+5 -> {0,1}", d.first == 0 && d.second == 1);
}

