steps.solution:
#include <stack>
#include <string>

bool balanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (st.empty()) return false;
            char open = st.top();
            st.pop();
            if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{')) return false;
        }
    }
    return st.empty();
}

steps.harness:
int main() {
    CHECK_EQ("()", balanced("()"), true);
    CHECK_EQ("([]{})", balanced("([]{})"), true);
    CHECK_EQ("(]", balanced("(]"), false);
    CHECK_EQ("((", balanced("(("), false);
    CHECK_EQ("))", balanced("))"), false);
    CHECK_EQ("code", balanced("int main() { return v[0]; }"), true);
    CHECK_EQ("empty", balanced(""), true);
    CHECK_EQ("([)]", balanced("([)]"), false);
}

