steps.solution:
#include <algorithm>
#include <numeric>
#include <vector>

double average_damage(const std::vector<int>& hits) {
    if (hits.empty()) return 0;
    return (double)std::accumulate(hits.begin(), hits.end(), 0) / hits.size();
}

std::vector<int> with_armor(const std::vector<int>& hits) {
    std::vector<int> out(hits.size());
    std::transform(hits.begin(), hits.end(), out.begin(), [](int h) { return h / 2; });
    return out;
}

steps.harness:
int main() {
