    CHECK("average of empty is 0", average_damage({}) == 0.0);
    CHECK_EQ("with_armor", with_armor({100, 27, 50}), std::vector<int>{50, 13, 25});
    CHECK_EQ("with_armor empty", with_armor({}), std::vector<int>{});
}

