#include <iterator>
#include <vector>

std::vector<int> above(const std::vector<int>& v, int threshold) {
    std::vector<int> out;
    std::copy_if(v.begin(), v.end(), std::back_inserter(out), [threshold](int x) { return x > threshold; });
    return out;
}

