class Buffer {
public:
    explicit Buffer(int n) : data_(new int[n]()), size_(n) {}
    ~Buffer() { delete[] data_; }
    Buffer(Buffer&& other) noexcept : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
    }
    // move assignment here
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            size_ = other.size_;
            other.data_ = nullptr;
            other.size_ = 0;
        }
        return *this;
    }
    int size() const { return size_; }
    const int* data() const { return data_; }

private:
    int* data_;
    int size_;
};

