steps.solution:
#include <cstddef>

template <typename T, std::size_t N>
class FixedStack {
public:
    bool push(const T& v) {
        if (count_ == N) return false;
        items_[count_++] = v;
        return true;
    }
    T pop() { return items_[--count_]; }
    std::size_t size() const { return count_; }
    bool full() const { return count_ == N; }
    static constexpr std::size_t capacity() { return N; }

private:
    T items_[N];
    std::size_t count_ = 0;
};

steps.harness:
