    CHECK_EQ("capacity comes from N", FixedStack<int, 3>::capacity(), 3u);
    CHECK_EQ("push 1", s.push(1), true);
    s.push(2);
    s.push(3);
    CHECK_EQ("full after 3", s.full(), true);
    CHECK_EQ("push when full fails", s.push(4), false);
    CHECK_EQ("size stays 3", s.size(), 3u);
    CHECK_EQ("pop returns the top", s.pop(), 3);
    CHECK_EQ("then 2", s.pop(), 2);
