#include <vector>

template <typename T>
class MinStack {
public:
    void push(const T& v) {
        items_.push_back(v);
        if (mins_.empty() || v < mins_.back() || v == mins_.back()) mins_.push_back(v);
    }
    void pop() {
        if (items_.back() == mins_.back()) mins_.pop_back();
        items_.pop_back();
    }
    const T& top() const { return items_.back(); }
    const T& min() const { return mins_.back(); }
    bool empty() const { return items_.empty(); }

private:
    std::vector<T> items_;
    std::vector<T> mins_;
};

