#include <algorithm>
#include <string>
#include <vector>

class Squad {
public:
    bool add(const std::string& name) {
        if (members_.size() >= 5) return false;
        if (std::find(members_.begin(), members_.end(), name) != members_.end()) return false;
        members_.push_back(name);
        return true;
    }
    bool remove(const std::string& name) {
        auto it = std::find(members_.begin(), members_.end(), name);
        if (it == members_.end()) return false;
        members_.erase(it);
        return true;
    }
    int size() const { return static_cast<int>(members_.size()); }
    std::string roster() const {
        std::string out;
        for (std::size_t i = 0; i < members_.size(); i++) {
            if (i) out += ", ";
            out += members_[i];
        }
        return out;
    }

private:
    std::vector<std::string> members_;
};

