steps.solution:
#include <deque>

class Clock {
public:
    virtual ~Clock() = default;
    virtual long now() const = 0;
};

class RateLimiter {
public:
    RateLimiter(const Clock& clock, int limit, long window) : clock_(clock), limit_(limit), window_(window) {}
    bool allow() {
        long t = clock_.now();
        while (!calls_.empty() && t >= calls_.front() + window_) calls_.pop_front();
        if (static_cast<int>(calls_.size()) >= limit_) return false;
        calls_.push_back(t);
        return true;
    }

private:
    const Clock& clock_;
    int limit_;
    long window_;
    std::deque<long> calls_;
};

