    CHECK_EQ("call 3", rl.allow(), true);
    CHECK_EQ("call 4 is over the limit", rl.allow(), false);
    clock.t = 9;
    CHECK_EQ("still inside the window at t=9", rl.allow(), false);
    clock.t = 10;
    CHECK_EQ("first two calls expire at t=10", rl.allow(), true);
    CHECK_EQ("one more fits", rl.allow(), true);
