std::vector<std::string> top_fraggers(const std::vector<std::pair<std::string, int>>& players, int min_kills) {
    std::vector<std::string> out;
    auto names = players
        | std::views::filter([min_kills](const auto& p) { return p.second >= min_kills; })
        | std::views::transform([](const auto& p) { return p.first; });
    for (const auto& n : names) out.push_back(n);
    return out;
}

