steps.solution:
#include <span>

int max_window(std::span<const int> xs, std::size_t k) {
    int cur = 0;
    for (std::size_t i = 0; i < k; i++) cur += xs[i];
    int best = cur;
    for (std::size_t i = k; i < xs.size(); i++) {
        cur += xs[i] - xs[i - k];
        if (cur > best) best = cur;
    }
    return best;
}

