#include <optional>
#include <string>

struct Result {
    std::optional<int> value;
    std::string error;
    bool ok() const { return value.has_value(); }
};

Result parse_money(const std::string& s) {
    if (s.empty() || s[0] != '$') return {std::nullopt, "missing $"};
    if (s.size() == 1) return {std::nullopt, "not a number"};
    long long v = 0;
    for (std::size_t i = 1; i < s.size(); i++) {
        if (s[i] < '0' || s[i] > '9') return {std::nullopt, "not a number"};
        if (v <= 16000) v = v * 10 + (s[i] - '0');
    }
    if (v > 16000) return {std::nullopt, "over the cap"};
    return {static_cast<int>(v), ""};
}

steps.harness:
int main() {
    auto a = parse_money("$2700");
    CHECK("$2700 ok", a.ok() && *a.value == 2700);
    CHECK_EQ("2700 without $", parse_money("2700").error, std::string("missing $"));
    CHECK_EQ("$", parse_money("$").error, std::string("not a number"));
    CHECK_EQ("$12a", parse_money("$12a").error, std::string("not a number"));
    CHECK_EQ("$20000", parse_money("$20000").error, std::string("over the cap"));
    CHECK_EQ("$99999999999", parse_money("$99999999999").error, std::string("over the cap"));
    CHECK("$16000 ok", parse_money("$16000").ok());
    CHECK_EQ("empty", parse_money("").error, std::string("missing $"));
}

