#include <map>
#include <sstream>
#include <string>

struct ConfigResult {
    std::map<std::string, std::string> values;
    std::string error;   // empty means success
};

ConfigResult load_config(const std::string& text) {
    ConfigResult r;
    std::istringstream in(text);
    std::string line;
    int n = 0;
    while (std::getline(in, line)) {
        n++;
        if (line.empty() || line[0] == '#') continue;
        std::size_t eq = line.find('=');
        std::string where = "line " + std::to_string(n) + ": ";
        if (eq == std::string::npos) return {{}, where + "missing ="};
        std::string key = line.substr(0, eq);
        if (key.empty()) return {{}, where + "empty key"};
        if (r.values.count(key)) return {{}, where + "duplicate key " + key};
        r.values[key] = line.substr(eq + 1);
    }
    return r;
}

