    {"T spawn", "Sand, crates and the smell of fresh bread.", {1, -1, -1, 2}, "bomb"},
    {"mid", "A long open corridor. Snipers love this place.", {3, -1, 0, -1}, NULL},
    {"tunnels", "Dark and narrow. Footsteps echo.", {-1, 0, -1, 3}, "flashbang"},
    {"A site", "The bombsite. Plant here.", {-1, -1, 1, -1}, NULL},
};

const char *inventory[8];
int carried = 0;

int direction(const char *w) {
    const char *names[] = {"north", "east", "south", "west"};
    for (int d = 0; d < 4; d++)
        if (strcmp(w, names[d]) == 0) return d;
    return -1;
}

int main(void) {
    int here = 0;
    char word[32];
    while (scanf("%31s", word) == 1) {
        // handle commands here
        if (strcmp(word, "look") == 0) {
            printf("%s\n%s\n", rooms[here].name, rooms[here].desc);
            if (rooms[here].item) printf("you see a %s\n", rooms[here].item);
        } else if (strcmp(word, "go") == 0) {
            char dir[16];
            scanf("%15s", dir);
            int d = direction(dir);
            if (d < 0 || rooms[here].exits[d] < 0) {
                printf("you can't go that way\n");
            } else {
                here = rooms[here].exits[d];
                printf("%s\n", rooms[here].name);
            }
        } else if (strcmp(word, "take") == 0) {
            if (!rooms[here].item) {
                printf("nothing here\n");
            } else {
                printf("you take the %s\n", rooms[here].item);
                inventory[carried++] = rooms[here].item;
                rooms[here].item = NULL;
            }
        } else if (strcmp(word, "inventory") == 0) {
            if (carried == 0) {
                printf("you carry nothing\n");
            } else {
                printf("you carry: ");
                for (int i = 0; i < carried; i++) printf("%s%s", i ? ", " : "", inventory[i]);
                printf("\n");
            }
        }
    }
    return 0;
}

