    int cols() const { return cols_; }
    double& at(int r, int c) { return data_[r * cols_ + c]; }
    double at(int r, int c) const { return data_[r * cols_ + c]; }

private:
    int rows_ = 0, cols_ = 0;
    std::vector<double> data_;
};

Matrix operator+(const Matrix& a, const Matrix& b) {
    Matrix out(a.rows(), a.cols());
    for (int r = 0; r < a.rows(); r++)
        for (int c = 0; c < a.cols(); c++) out.at(r, c) = a.at(r, c) + b.at(r, c);
    return out;
}

bool operator==(const Matrix& a, const Matrix& b) {
    if (a.rows() != b.rows() || a.cols() != b.cols()) return false;
    for (int r = 0; r < a.rows(); r++)
        for (int c = 0; c < a.cols(); c++)
            if (a.at(r, c) != b.at(r, c)) return false;
    return true;
}

Matrix operator*(const Matrix& m, double k) {
    Matrix out(m.rows(), m.cols());
    for (int r = 0; r < m.rows(); r++)
        for (int c = 0; c < m.cols(); c++) out.at(r, c) = m.at(r, c) * k;
    return out;
}

