class Matrix {
public:
    Matrix(int rows, int cols) : rows_(rows), cols_(cols), data_(rows * cols, 0.0) {}
    int rows() const { return rows_; }
    int cols() const { return cols_; }
    double& at(int r, int c) { return data_[r * cols_ + c]; }
    double at(int r, int c) const { return data_[r * cols_ + c]; }
    static Matrix identity(int n) {
        Matrix m(n, n);
        for (int i = 0; i < n; i++) m.at(i, i) = 1;
        return m;
    }
    Matrix transpose() const {
        Matrix t(cols_, rows_);
        for (int r = 0; r < rows_; r++)
            for (int c = 0; c < cols_; c++) t.at(c, r) = at(r, c);
        return t;
    }
    double determinant() const {
        if (rows_ == 1) return at(0, 0);
        double det = 0;
        for (int c = 0; c < cols_; c++) {
            Matrix minor(rows_ - 1, cols_ - 1);
            for (int r = 1; r < rows_; r++) {
                int mc = 0;
                for (int k = 0; k < cols_; k++) {
                    if (k == c) continue;
                    minor.at(r - 1, mc++) = at(r, k);
