#include <iostream>
#include <map>
#include <string>

std::map<std::string, long long> vars;

struct Parser {
    const std::string& s;
    std::size_t i = 0;
    std::string error{};

    void fail(const std::string& msg) {
        if (error.empty()) error = msg;
    }
    void skip() {
        while (i < s.size() && s[i] == ' ') i++;
    }
    bool eat(char c) {
        skip();
        if (i < s.size() && s[i] == c) {
            i++;
            return true;
        }
        return false;
    }
    static bool is_name_char(char c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }
    std::string name() {
        skip();
        std::string n;
        while (i < s.size() && is_name_char(s[i])) n += s[i++];
        return n;
    }
    long long number() {
        skip();
        if (i >= s.size() || s[i] < '0' || s[i] > '9') {
            fail("syntax");
            return 0;
        }
        long long v = 0;
        while (i < s.size() && s[i] >= '0' && s[i] <= '9') v = v * 10 + (s[i++] - '0');
        return v;
    }
    long long factor() {
        if (!error.empty()) return 0;
        if (eat('-')) return -factor();
        if (eat('(')) {
            long long v = expr();
            if (!eat(')')) fail("syntax");
            return v;
        }
        skip();
        if (i < s.size() && is_name_char(s[i])) {
            std::string n = name();
            auto it = vars.find(n);
            if (it == vars.end()) {
                fail("unknown variable " + n);
                return 0;
            }
            return it->second;
        }
        return number();
    }
    long long term() {
        long long v = factor();
        while (error.empty()) {
            if (eat('*')) {
                v *= factor();
            } else if (eat('/')) {
                long long d = factor();
                if (!error.empty()) break;
                if (d == 0) {
                    fail("division by zero");
                    break;
                }
                v /= d;
            } else {
                break;
            }
        }
        return v;
    }
    long long expr() {
        long long v = term();
        while (error.empty()) {
            if (eat('+')) v += term();
            else if (eat('-')) v -= term();
            else break;
        }
        return v;
    }
    bool at_end() {
        skip();
        return i == s.size();
    }
};

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        // evaluate the line and print the result
        Parser p{line};
        p.skip();
        bool is_let = line.compare(p.i, 4, "let ") == 0;
        std::string n;
        if (is_let) {
            p.i += 4;
            n = p.name();
            if (n.empty() || !p.eat('=')) p.fail("syntax");
        }
        long long v = p.error.empty() ? p.expr() : 0;
        if (p.error.empty() && !p.at_end()) p.fail("syntax");
        if (!p.error.empty()) {
            std::cout << "error: " << p.error << "\n";
        } else if (is_let) {
            vars[n] = v;
            std::cout << n << " = " << v << "\n";
        } else {
            std::cout << v << "\n";
        }
    }
}

