#define BLOCK 16
#define BLOCKS 32
static _Alignas(16) unsigned char pool[BLOCK * BLOCKS];
static void *free_list = NULL;

void pool_init(void) {
    for (int i = 0; i < BLOCKS; i++) {
        void **block = (void **)(pool + i * BLOCK);
        *block = (i + 1 < BLOCKS) ? (void *)(pool + (i + 1) * BLOCK) : NULL;
    }
    free_list = pool;
}

void *pool_alloc(void) {
    if (free_list == NULL) return NULL;
    void *p = free_list;
    free_list = *(void **)p;
    return p;
}

void pool_free(void *p) {
    *(void **)p = free_list;
    free_list = p;
}

