    return p;
}

int pool_owns(const void *p) {
    uintptr_t start = (uintptr_t)pool, addr = (uintptr_t)p;
    if (addr < start || addr >= start + sizeof(pool)) return 0;
    return (addr - start) % BLOCK == 0;
}

void pool_free(void *p) {
    if (!pool_owns(p)) return;
    *(void **)p = free_list;
    free_list = p;
}

int pool_available(void) {
    int n = 0;
    for (void *p = free_list; p != NULL; p = *(void **)p) n++;
    return n;
}

milestones.harness:
int main(void) {
    pool_init();
    CHECK_INT("32 available", pool_available(), 32);
    char *a = pool_alloc();
    CHECK_INT("31 after one alloc", pool_available(), 31);
    CHECK("owns a", pool_owns(a));
    CHECK("not the middle of a block", !pool_owns(a + 3));
    int outside;
    CHECK("not a stack variable", !pool_owns(&outside));
    CHECK("not NULL", !pool_owns(NULL));
    pool_free(&outside);
    CHECK_INT("foreign free ignored", pool_available(), 31);
    pool_free(a);
    CHECK_INT("back to 32", pool_available(), 32);
    return 0;
}

