    CHECK_INT("4721", digit_sum(4721), 14);
    CHECK_INT("0", digit_sum(0), 0);
    CHECK_INT("9", digit_sum(9), 9);
    CHECK_INT("1000000", digit_sum(1000000), 1);
    return 0;
}

