    CHECK("not NULL", a != NULL);
    CHECK("all 7", a[0] == 7 && a[1] == 7 && a[2] == 7 && a[3] == 7);
    free(a);
    int *b = repeat(-1, 1000);
    CHECK_INT("b[999]", b[999], -1);
    free(b);
    return 0;
}

