exercise.solution:
int count_words(const char *s) {
    int n = 0, in_word = 0;
    for (; *s; s++) {
        if (*s == ' ') {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            n++;
        }
    }
    return n;
}

exercise.harness:
int main(void) {
    CHECK_INT("\"rush b\"", count_words("rush b"), 2);
    CHECK_INT("\"  rush  b now \"", count_words("  rush  b now "), 3);
    CHECK_INT("empty", count_words(""), 0);
    CHECK_INT("spaces only", count_words("    "), 0);
    CHECK_INT("one", count_words("eco"), 1);
    return 0;
}

