class Counter {
public:
    void add(int n) {
        value_ += n;
        if (value_ > max_) max_ = value_;
    }
    void reset() { value_ = 0; }
    int value() const { return value_; }
    int max_seen() const { return max_; }

private:
    int value_ = 0;
    int max_ = 0;
};

