exercise.solution:
#include <optional>
#include <utility>
#include <vector>

std::optional<std::pair<int, int>> find_pair(const std::vector<int>& v, int target) {
    for (std::size_t i = 0; i < v.size(); i++)
        for (std::size_t j = i + 1; j < v.size(); j++)
            if (v[i] + v[j] == target) return std::pair{v[i], v[j]};
    return std::nullopt;
}

