exercise.solution:
#include <string>
#include <utility>

class Token {
public:
    explicit Token(std::string id) : id_(std::move(id)) {}
    Token(const Token&) = delete;
    Token& operator=(const Token&) = delete;
    Token(Token&& o) noexcept : id_(std::move(o.id_)) { o.id_.clear(); }
    Token& operator=(Token&& o) noexcept {
        id_ = std::move(o.id_);
        o.id_.clear();
        return *this;
    }
    const std::string& id() const { return id_; }

private:
    std::string id_;
};

exercise.harness:
#include <type_traits>
#include <utility>
int main() {
    CHECK("not copyable", !std::is_copy_constructible_v<Token>);
    Token a("abc");
    Token b(std::move(a));
    CHECK_EQ("moved id", b.id(), std::string("abc"));
    CHECK_EQ("source emptied", a.id(), std::string(""));
    Token c("x");
    c = std::move(b);
    CHECK_EQ("move assigned", c.id(), std::string("abc"));
}

