exercise.solution:
#include <memory>
#include <string>
#include <vector>

struct Shape {
    virtual double area() const = 0;
    virtual std::string name() const = 0;
    virtual ~Shape() = default;
};

struct Circle : Shape {
    double r;
    explicit Circle(double r) : r(r) {}
    double area() const override { return 3.14159 * r * r; }
    std::string name() const override { return "circle"; }
};

struct Square : Shape {
    double s;
    explicit Square(double s) : s(s) {}
    double area() const override { return s * s; }
    std::string name() const override { return "square"; }
};

std::string largest(const std::vector<std::unique_ptr<Shape>>& v) {
    const Shape* best = v[0].get();
    for (const auto& p : v)
        if (p->area() > best->area()) best = p.get();
    return best->name();
}

exercise.harness:
int main() {
    std::vector<std::unique_ptr<Shape>> v;
    v.push_back(std::make_unique<Square>(3));
    v.push_back(std::make_unique<Circle>(2));
    CHECK_EQ("circle r=2 beats square 3", largest(v), std::string("circle"));
    v.push_back(std::make_unique<Square>(4));
    CHECK_EQ("square 4 wins", largest(v), std::string("square"));
}

