#include <memory>
#include <vector>

std::unique_ptr<std::vector<int>> make_scores(int n) {
    if (n <= 0) return nullptr;
    auto v = std::make_unique<std::vector<int>>();
    for (int i = 1; i <= n; i++) v->push_back(i);
    return v;
}

exercise.harness:
int main() {
    auto a = make_scores(3);
    CHECK("not null", a != nullptr);
    CHECK_EQ("contents", *a, std::vector<int>{1, 2, 3});
    CHECK("n=0 gives nullptr", make_scores(0) == nullptr);
}

