#include <vector>

template <typename T>
T max_of(const std::vector<T>& v) {
    T best = v[0];
    for (const auto& x : v)
        if (best < x) best = x;
    return best;
}

exercise.harness:
int main() {
    CHECK_EQ("ints", max_of(std::vector<int>{3, 9, 2}), 9);
    CHECK_EQ("strings", max_of(std::vector<std::string>{"b", "z", "a"}), std::string("z"));
    CHECK_EQ("doubles", max_of(std::vector<double>{-1.5, -0.5}), -0.5);
}

