exercise.solution:
#include <vector>

std::vector<int> evens(const std::vector<int>& v) {
    std::vector<int> out;
    for (int x : v)
        if (x % 2 == 0) out.push_back(x);
    return out;
}

exercise.harness:
int main() {
    CHECK_EQ("mixed", evens({1, 2, 3, 4, 6}), std::vector<int>{2, 4, 6});
    CHECK_EQ("none", evens({1, 3}), std::vector<int>{});
    CHECK_EQ("negatives", evens({-2, -1, 0}), std::vector<int>{-2, 0});
}

