exercise.solution:
#include <string>
#include <vector>

std::string join(const std::vector<std::string>& parts, const std::string& sep) {
    std::string out;
    for (std::size_t i = 0; i < parts.size(); i++) {
        if (i) out += sep;
        out += parts[i];
    }
    return out;
}

exercise.harness:
int main() {
    CHECK_EQ("a, b, c", join({"a", "b", "c"}, ", "), std::string("a, b, c"));
    CHECK_EQ("single", join({"x"}, "-"), std::string("x"));
    CHECK_EQ("empty", join({}, "-"), std::string(""));
}
